import{_ as a,o as t,c as o,a2 as l}from"./chunks/framework.Bg-Zxr5O.js";const u=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-zh/Set-Membership.md","filePath":"manual-zh/Set-Membership.md","lastUpdated":1785684581000}'),r={name:"manual-zh/Set-Membership.md"};function s(n,e,i,p,h,_){return t(),o("div",null,[...e[0]||(e[0]=[l('<h4 id="_7-7-5-集合成员函数" tabindex="-1">7.7.5 集合成员函数 <a class="header-anchor" href="#_7-7-5-集合成员函数" aria-label="Permalink to &quot;7.7.5 集合成员函数&quot;">​</a></h4><p>集合成员函数判断某个取值是否为某个集合的成员。它们接受一组数值参数或一组字符串参数，并产生布尔结果。</p><p>字符串比较按照 <a href="./Relational-Operators">Relational Operators</a> 中给出的规则执行。用户缺失字符串值被视为有效值。</p><p>Function: __<strong>ANY</strong> <em>( value, set [, set]…)</em></p><p>如果 value 等于 set 中任意一个取值，则返回真，否则返回假。对于数值参数，如果 value 为系统缺失，或 set 中所有取值都为系统缺失，则返回系统缺失。如果 value</p><p>Function: __<strong>RANGE</strong> <em>( value, low, high [, low, high]…)</em></p><p>如果 value 落在任意一个由 low 和 high（含端点）所界定区间内，则返回真，否则返回假。low 和 high 必须成对给出。如果任一 high 小于其 low，或对于数值参数，如果 value 为系统缺失，或所有 low-high 对都包含一个（或两个）系统缺失值，则返回系统缺失。如果 low 或 high 存在缺失，则该对不与 value 匹配，即使 value 等于那个非缺失的端点。</p>',7)])])}const c=a(r,[["render",s]]);export{u as __pageData,c as default};
